INSERT INTO "University" ("id", "name", "nameAr", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "isFeatured", "isRecommended", "isTrending", "publishedAt", "latitude", "longitude", "createdAt", "updatedAt") VALUES
  ('univ_56a1915665594b94a4fd', 'Badr University in Cairo', 'جامعة بدر بالقاهرة', 'badr-university-in-cairo', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Badr City', 'مدينة بدر', 'A private university in Badr City, northeast Cairo, offering programs across engineering, medicine, dentistry, business, and the arts.', NULL, NULL, NULL, 'https://www.buc.edu.eg', NULL, 'https://images.unsplash.com/photo-1607237138185-eedd9c632b0b?auto=format&fit=crop&w=1200&q=70', 2014, NULL, NULL, NULL, NULL, TRUE, FALSE, TRUE, NOW(), 30.1667, 31.7333, NOW(), NOW()),
  ('univ_4889afde74d0434d823a', 'The British University in Egypt', 'الجامعة البريطانية في مصر', 'british-university-in-egypt', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'El Shorouk City', 'مدينة الشروق', 'Founded in 2005 through an inter-governmental agreement, BUE delivers a British-style education in El Shorouk City, Cairo, with degrees validated by UK partner universities.', NULL, NULL, NULL, 'https://www.bue.edu.eg', NULL, 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?auto=format&fit=crop&w=1200&q=70', 2005, NULL, NULL, NULL, NULL, TRUE, TRUE, FALSE, NOW(), 30.1204, 31.6136, NOW(), NOW()),
  ('univ_e80813fc288f41c29f09', 'Future University in Egypt', 'جامعة المستقبل بمصر', 'future-university-in-egypt', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'New Cairo', 'القاهرة الجديدة', 'Established by presidential decree in 2006, FUE sits in the heart of New Cairo and offers programs across engineering, pharmacy, dentistry, computing, and business.', NULL, NULL, NULL, 'https://www.fue.edu.eg', NULL, 'https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=70', 2006, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, NOW(), 30.0189, 31.4783, NOW(), NOW()),
  ('univ_553d160ea8f44141afea', 'German University in Cairo', 'الجامعة الألمانية بالقاهرة', 'german-university-in-cairo-guc', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'New Cairo', 'القاهرة الجديدة', 'The first German university established outside Germany, founded in cooperation with the Universities of Ulm and Stuttgart and inaugurated in New Cairo in 2003.', NULL, NULL, NULL, 'https://www.guc.edu.eg', NULL, 'https://images.unsplash.com/photo-1498243691581-b145c3f54a5a?auto=format&fit=crop&w=1200&q=70', 2003, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NOW(), 29.987, 31.44, NOW(), NOW()),
  ('univ_f590aec6095a4ac88b63', 'Misr International University', 'جامعة مصر الدولية', 'misr-international-university-miu', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Cairo', 'القاهرة', 'Founded in 1996 at Km 28 of the Cairo-Ismailia Road, MIU is one of Egypt''s earliest private universities, known for its business, pharmacy, and applied linguistics programs.', NULL, NULL, NULL, 'https://www.miuegypt.edu.eg', NULL, 'https://images.unsplash.com/photo-1562774053-701939374585?auto=format&fit=crop&w=1200&q=70', 1996, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, NOW(), 30.197, 31.639, NOW(), NOW()),
  ('univ_3b6b7d07582f4f2dbabd', 'Misr University for Science and Technology', 'جامعة مصر للعلوم والتكنولوجيا', 'misr-university-for-science-and-technology', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', '6th of October City', 'مدينة 6 أكتوبر', 'Established by presidential decree in 1996, MUST is one of Egypt''s largest private universities, with a broad medical, engineering, and health-sciences offering in 6th of October City, Giza.', NULL, NULL, NULL, 'https://www.must.edu.eg', NULL, 'https://images.unsplash.com/photo-1591123120675-6f7f1aae0e5b?auto=format&fit=crop&w=1200&q=70', 1996, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NOW(), 29.966, 30.9232, NOW(), NOW()),
  ('univ_8e68d213bb684056821a', 'Nile University', 'جامعة النيل', 'nile-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Sheikh Zayed City', 'مدينة الشيخ زايد', 'A research-focused, non-profit university established in 2006 in Sheikh Zayed City, Giza, built around applied-science schools rather than traditional faculties.', NULL, NULL, NULL, 'https://www.nu.edu.eg', NULL, 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?auto=format&fit=crop&w=1200&q=70', 2006, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NOW(), 30.0778, 30.9757, NOW(), NOW()),
  ('univ_4307d8a0930144f9a5e8', 'October 6 University', 'جامعة 6 أكتوبر', 'october-6-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', '6th of October City', 'مدينة 6 أكتوبر', 'Egypt''s first private university, established in 1996 in 6th of October City, Giza, with a strong focus on medicine, dentistry, and pharmacy.', NULL, NULL, NULL, 'https://www.o6u.edu.eg', NULL, 'https://images.unsplash.com/photo-1571260899304-425eee4c7efc?auto=format&fit=crop&w=1200&q=70', 1996, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, NOW(), 29.966, 30.9232, NOW(), NOW());
